//! Q3: the Rust port of Svelte's CSS pipeline (`svelters_compiler::svelte::css`) against
//! svelte/compiler 5.57.2 on a checked-in corpus (tests/css_scope/corpus.json, generated by
//! `node tools/oracle/gen-css.mjs`): every `.svelte` with a `<style>` in Svelte's test samples and
//! in this repo. Per case, byte-identical `css.code` (`css: 'external'` and, unless dev, the
//! minified `css: 'injected'` one), `hasGlobal`, the `css_*` warnings, the CSS compile errors and
//! the default `cssHash`.
//!
//! `cargo nextest run -p svelters-compiler --test css_scope` (set `CSS_SCOPE_FILTER=<id substring>`
//! to run some cases, `CSS_SCOPE_SHOW=n` to print more failures).

use serde_json::Value;
use svelters_compiler::svelte::css::{compile_css, css_hash, CssHash, CssOptions};
use svelters_compiler::svelte::parse::{parse, ParseOptions};
use svelters_compiler::svelte::scope::analyze::analyze_component_scopes;

/// Byte offset -> UTF-16 offset.
fn utf16(src: &str, byte: u32) -> u64 {
    src[..byte as usize].encode_utf16().count() as u64
}

fn compare_error(case: &Value, src: &str, result: Result<(), svelters_compiler::svelte::errors::CompileError>) -> Result<(), String> {
    let e = &case["error"];
    match result {
        Ok(_) if e.is_null() => Err("unreachable".into()),
        Ok(_) => Err(format!("expected error {} {:?}, ours compiled", e["code"], e["message"])),
        Err(err) if e.is_null() => Err(format!("ours failed: {} {} at {}", err.code, err.message, utf16(src, err.start))),
        Err(err) => {
            let (s, en) = (utf16(src, err.start), utf16(src, err.end));
            if e["code"] == err.code && e["message"] == err.message.as_str() && e["start"].as_u64() == Some(s) && e["end"].as_u64() == Some(en) {
                Ok(())
            } else {
                Err(format!("expected error {} {:?} [{}, {}], ours {} {:?} [{s}, {en}]", e["code"], e["message"], e["start"], e["end"], err.code, err.message))
            }
        }
    }
}

fn run_case(case: &Value) -> Result<(), String> {
    let src = case["source"].as_str().unwrap();
    let options = &case["options"];
    let dev = options["dev"] == true;
    let runes = options["runes"].as_bool();

    let fixed = case["hash"].as_str().unwrap_or("svelte-xyz").to_string();
    let opts = CssOptions { hash: CssHash::Fixed(fixed), injected: false, dev };

    // a CSS syntax error is a parse error, upstream and here
    let parsed = parse(src, &ParseOptions { loose: false, native: false });
    let mut root = match parsed {
        Ok(r) => r,
        Err(err) => return compare_error(case, src, Err(err)),
    };
    svelters_compiler::svelte::ts::strip(&mut root, src).map_err(|e| format!("ts strip failed: {}", e.code))?;
    let root_ref = &root;
    let analysis = analyze_component_scopes(root_ref, runes).map_err(|e| format!("scope analysis failed: {} {}", e.code, e.message))?;
    let result = compile_css(src, root_ref, &analysis, &opts);
    if !case["error"].is_null() {
        return compare_error(case, src, result.map(|_| ()));
    }
    let out = result.map_err(|e| format!("ours failed: {} {} at {}", e.code, e.message, utf16(src, e.start)))?;
    let ext = &case["external"];
    let Some(out) = out else {
        return if ext["code"].is_null() { Ok(()) } else { Err("ours: no <style>".into()) };
    };

    let mut errs = Vec::new();
    if out.injected {
        // `<svelte:options css="injected">` or a custom element: upstream's `css` is null
        if !ext["code"].is_null() {
            errs.push("ours injects the styles, upstream does not".into());
        }
        if let Some(expected) = case["injected"].as_str() {
            if expected != out.code {
                errs.push(format!("injected code differs:\n--- expected\n{expected}\n--- ours\n{}", out.code));
            }
        }
        return if errs.is_empty() { Ok(()) } else { Err(errs.join("\n")) };
    }
    if ext["code"].as_str() != Some(out.code.as_str()) {
        errs.push(format!("external code differs:\n--- expected\n{}\n--- ours\n{}", ext["code"].as_str().unwrap_or("<null>"), out.code));
    }
    if ext["hasGlobal"].as_bool() != Some(out.has_global) {
        errs.push(format!("hasGlobal: expected {}, ours {}", ext["hasGlobal"], out.has_global));
    }
    let ours_w: Vec<Value> = out
        .warnings
        .iter()
        .map(|w| serde_json::json!({"code": w.code, "message": w.message, "start": utf16(src, w.start), "end": utf16(src, w.end)}))
        .collect();
    if ext["warnings"].as_array().map(|a| a.as_slice()) != Some(ours_w.as_slice()) {
        errs.push(format!("warnings: expected {}, ours {}", ext["warnings"], Value::Array(ours_w)));
    }

    if let Some(expected) = case["injected"].as_str() {
        let opts = CssOptions { injected: true, ..opts };
        match compile_css(src, root_ref, &analysis, &opts) {
            Ok(Some(o)) if o.code == expected => {}
            Ok(Some(o)) => errs.push(format!("injected code differs:\n--- expected\n{expected}\n--- ours\n{}", o.code)),
            other => errs.push(format!("injected: ours {:?}", other.map(|o| o.map(|o| o.code)))),
        }
    }

    let styles = &root_ref.css.as_ref().unwrap().content.styles;
    if let Some(h) = case["default_hash_css"].as_str() {
        let ours = css_hash(&CssHash::Default { filename: None }, styles);
        if ours != h {
            errs.push(format!("default hash of the css: expected {h}, ours {ours}"));
        }
    }
    if let (Some(h), Some(f)) = (case["default_hash_filename"].as_str(), case["hash_args"]["filename"].as_str().or(Some("(unknown)"))) {
        let ours = css_hash(&CssHash::Default { filename: Some(f.to_string()) }, styles);
        if ours != h {
            errs.push(format!("default hash of the filename: expected {h}, ours {ours}"));
        }
    }
    if errs.is_empty() {
        Ok(())
    } else {
        Err(errs.join("\n"))
    }
}

#[test]
fn css_scope_corpus() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/css_scope/corpus.json");
    let corpus: Value = serde_json::from_str(&std::fs::read_to_string(path).expect("corpus.json")).expect("json");
    assert_eq!(corpus["svelte"], "5.57.2");
    let filter = std::env::var("CSS_SCOPE_FILTER").ok();
    let show: usize = std::env::var("CSS_SCOPE_SHOW").ok().and_then(|s| s.parse().ok()).unwrap_or(20);

    let mut failures = Vec::new();
    let mut total = 0;
    for case in corpus["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        if filter.as_deref().is_some_and(|f| !id.contains(f)) {
            continue;
        }
        total += 1;
        let r = std::panic::catch_unwind(|| run_case(case)).unwrap_or_else(|p| {
            Err(format!("panicked: {}", p.downcast_ref::<String>().cloned().or_else(|| p.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default()))
        });
        if let Err(e) = r {
            failures.push((id.to_string(), e));
        }
    }
    for (id, e) in failures.iter().take(show) {
        println!("=== {id}\n{e}\n");
    }
    println!("css_scope: {} / {total} pass", total - failures.len());
    assert!(failures.is_empty(), "{} of {total} cases differ from svelte 5.57.2 (see above)", failures.len());
}
